import {blend,clamp} from "./face.js";
function rgba(c,a){return `rgba(${c[0]},${c[1]},${c[2]},${a})`}
function smooth(data,w,h,r){const out=new Uint8ClampedArray(data),radius=Math.max(1,Math.min(4,Math.round(r))),src=new Uint8ClampedArray(data);for(let y=0;y<h;y++)for(let x=0;x<w;x++){let R=0,G=0,B=0,n=0;for(let yy=Math.max(0,y-radius);yy<=Math.min(h-1,y+radius);yy++)for(let xx=Math.max(0,x-radius);xx<=Math.min(w-1,x+radius);xx++){const p=(yy*w+xx)*4;R+=src[p];G+=src[p+1];B+=src[p+2];n++}const p=(y*w+x)*4;out[p]=R/n;out[p+1]=G/n;out[p+2]=B/n}return out}
function skinWeight(r,g,b){const max=Math.max(r,g,b),min=Math.min(r,g,b),sat=max?1-min/max:0;const warm=(r-g*.72-b*.55)/255;return clamp((warm+.08)/.55)*clamp((sat-.08)/.55)*clamp((max-35)/180)}
export function beauty(data,w,h,faceMask,featureProtection,settings){const soft=settings.soft/100,tone=settings.tone/100,light=settings.light/100;const sm=soft?smooth(data,w,h,1+soft*3):data;const out=new Uint8ClampedArray(data);for(let p=0,i=0;i<faceMask.length;i++,p+=4){const m=(faceMask[i]/255)*skinWeight(data[p],data[p+1],data[p+2])*(1-(featureProtection[i]/255)*.9);if(m<=.001)continue;const a=m*(.12+soft*.42);out[p]=data[p]+(sm[p]-data[p])*a;out[p+1]=data[p+1]+(sm[p+1]-data[p+1])*a;out[p+2]=data[p+2]+(sm[p+2]-data[p+2])*a;const y=.2126*out[p]+.7152*out[p+1]+.0722*out[p+2];const lift=light*.10*m*clamp((235-y)/80);out[p]=Math.min(255,out[p]+out[p]*lift);out[p+1]=Math.min(255,out[p+1]+out[p+1]*lift);out[p+2]=Math.min(255,out[p+2]+out[p+2]*lift)}return out}
export function masks(w,h,points){const c=document.createElement("canvas");c.width=w;c.height=h;const x=c.getContext("2d");const poly=[10,338,297,332,284,251,389,356,454,323,361,288,397,365,379,378,400,377,152,148,176,149,150,136,172,58,132,93,234,127,162,21,54,103,67,109];x.fillStyle="#fff";x.beginPath();poly.map(i=>[points[i].x*w,points[i].y*h]).forEach((p,i)=>i?x.lineTo(...p):x.moveTo(...p));x.closePath();x.fill();const face=x.getImageData(0,0,w,h).data; x.clearRect(0,0,w,h);x.fillStyle="#fff";for(const ids of [[33,160,158,133,153,144],[362,385,387,263,373,380],[61,146,91,181,84,17,314,405,321,375,291,308,324,318,402,317,14,87,178,88,95],[70,63,105,66,107],[336,296,334,293,300]]){const q=ids.map(i=>[points[i].x*w,points[i].y*h]);x.beginPath();x.moveTo(...q[0]);q.slice(1).forEach(p=>x.lineTo(...p));x.closePath();x.fill()}const blurCanvas=document.createElement("canvas");blurCanvas.width=w;blurCanvas.height=h;const b=blurCanvas.getContext("2d");b.filter="blur(6px)";b.globalAlpha=.82;b.drawImage(c,0,0);const protect=b.getImageData(0,0,w,h).data;return{face,protect}}
export function makeup(ctx,points,w,h,amount,look,expression){const a=amount/100;if(!a)return;const p=i=>[points[i].x*w,points[i].y*h],style={natural:{lip:[190,65,82],blush:[230,90,115],brow:[65,45,40],shadow:[160,110,145]},rose:{lip:[214,58,90],blush:[238,86,120],brow:[60,42,42],shadow:[185,115,155]},warm:{lip:[198,70,52],blush:[235,112,76],brow:[72,50,38],shadow:[178,112,82]}}[look]||null;if(!style)return;function ellipse(cx,cy,rx,ry,c,alpha){const g=ctx.createRadialGradient(cx,cy,0,cx,cy,rx);g.addColorStop(0,rgba(c,alpha));g.addColorStop(1,rgba(c,0));ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(cx,cy,rx,ry,0,0,Math.PI*2);ctx.fill()}ctx.save();const l=p(CHEEK_L),r=p(CHEEK_R);ellipse(l[0],l[1]+h*.015,w*.07,h*.045,style.blush,.22*a);ellipse(r[0],r[1]+h*.015,w*.07,h*.045,style.blush,.22*a);const jaw=blend(expression,"jawOpen");const mouth=p(13);ellipse(mouth[0],mouth[1],w*.065,h*.025*(1+jaw),style.lip,.26*a);for(const ids of [BROW_L,BROW_R]){ctx.strokeStyle=rgba(style.brow,.45*a);ctx.lineWidth=Math.max(2,w*.004);ctx.beginPath();ids.forEach((i,j)=>j?ctx.lineTo(...p(i)):ctx.moveTo(...p(i)));ctx.stroke()}for(const ids of [EYE_L,EYE_R]){const q=ids.map(p),cx=q.reduce((s,v)=>s+v[0],0)/q.length,cy=q.reduce((s,v)=>s+v[1],0)/q.length,blink=ids===EYE_L?blend(expression,"eyeBlinkLeft"):blend(expression,"eyeBlinkRight");ellipse(cx,cy-h*.008,w*.055,h*.022*(1-blink*.7),style.shadow,.13*a)}ctx.restore()}